CREATE TABLE IF NOT EXISTS auth_user (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, email_verified boolean NOT NULL DEFAULT false, image text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_session (id text PRIMARY KEY, expires_at timestamptz NOT NULL, token text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ip_address text, user_agent text, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS auth_account (id text PRIMARY KEY, account_id text NOT NULL, provider_id text NOT NULL, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, access_token text, refresh_token text, id_token text, access_token_expires_at timestamptz, refresh_token_expires_at timestamptz, scope text, password text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS organizations (id text PRIMARY KEY, name text NOT NULL, time_zone text NOT NULL DEFAULT 'Asia/Jerusalem');
CREATE TABLE IF NOT EXISTS companies (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), name text NOT NULL, UNIQUE(organization_id,id));
CREATE TABLE IF NOT EXISTS domains (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), name text NOT NULL, color text NOT NULL DEFAULT '#267d75', UNIQUE(organization_id,id));
CREATE TABLE IF NOT EXISTS memberships (id text PRIMARY KEY, user_id text NOT NULL REFERENCES auth_user(id), organization_id text NOT NULL REFERENCES organizations(id), role text NOT NULL CHECK(role IN ('deputy','staff','company_commander','contributor','viewer','admin')), company_id text, domain_id text, active boolean NOT NULL DEFAULT true, UNIQUE(user_id,organization_id), FOREIGN KEY(organization_id,company_id) REFERENCES companies(organization_id,id), FOREIGN KEY(organization_id,domain_id) REFERENCES domains(organization_id,id));
CREATE TABLE IF NOT EXISTS tasks (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), company_id text, domain_id text NOT NULL, title text NOT NULL CHECK(length(trim(title))>0), description text NOT NULL DEFAULT '', creator_id text NOT NULL REFERENCES auth_user(id), owner_id text NOT NULL REFERENCES auth_user(id), priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','blocked','pending_review','completed','cancelled')), due_date date, completed_at timestamptz, completed_by text REFERENCES auth_user(id), blocker_reason text, requires_review boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), FOREIGN KEY(organization_id,company_id) REFERENCES companies(organization_id,id), FOREIGN KEY(organization_id,domain_id) REFERENCES domains(organization_id,id), CHECK((status='completed')=(completed_at IS NOT NULL)), CHECK(status <> 'blocked' OR length(trim(blocker_reason))>0));
CREATE INDEX IF NOT EXISTS tasks_scope_status ON tasks(organization_id,company_id,status);
CREATE INDEX IF NOT EXISTS tasks_owner ON tasks(owner_id);
CREATE TABLE IF NOT EXISTS task_comments (id text PRIMARY KEY, task_id text NOT NULL REFERENCES tasks(id), actor_id text NOT NULL REFERENCES auth_user(id), body text NOT NULL CHECK(length(trim(body))>0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS decisions (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), company_id text, domain_id text NOT NULL, title text NOT NULL CHECK(length(trim(title))>0), description text NOT NULL DEFAULT '', requester_id text NOT NULL REFERENCES auth_user(id), decider_id text NOT NULL REFERENCES auth_user(id), priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','clarification_requested','approved','rejected')), notes text, task_id text, resolved_at timestamptz, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), FOREIGN KEY(organization_id,company_id) REFERENCES companies(organization_id,id), FOREIGN KEY(organization_id,domain_id) REFERENCES domains(organization_id,id), FOREIGN KEY(organization_id,task_id) REFERENCES tasks(organization_id,id));
CREATE INDEX IF NOT EXISTS decisions_scope_status ON decisions(organization_id,company_id,status);
CREATE TABLE IF NOT EXISTS audit_events (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), entity_type text NOT NULL, entity_id text NOT NULL, actor_id text NOT NULL REFERENCES auth_user(id), action text NOT NULL, summary text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_org_created ON audit_events(organization_id,created_at);
CREATE TABLE IF NOT EXISTS auth_rate_limit (id text PRIMARY KEY, key text NOT NULL UNIQUE, count integer NOT NULL, last_request bigint NOT NULL);
CREATE TABLE IF NOT EXISTS mutation_receipts (key text PRIMARY KEY, fingerprint text NOT NULL, result jsonb, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE tasks DROP CONSTRAINT IF EXISTS tasks_blocked_reason;
ALTER TABLE tasks ADD CONSTRAINT tasks_blocked_reason CHECK(status <> 'blocked' OR (blocker_reason IS NOT NULL AND length(trim(blocker_reason))>0));
ALTER TABLE tasks DROP CONSTRAINT IF EXISTS tasks_completion_actor;
ALTER TABLE tasks ADD CONSTRAINT tasks_completion_actor CHECK((status='completed')=(completed_by IS NOT NULL));
CREATE OR REPLACE FUNCTION prevent_audit_modification() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit events are immutable'; END; $$;
DROP TRIGGER IF EXISTS audit_immutable ON audit_events;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION prevent_audit_modification();
